MOD = 51123987

def count_crossing_palindromes(n, s):
    # Manacher's algorithm to find all palindromic substrings
    T = '#'.join(f'^{s}$')
    P = [0] * len(T)
    C = R = 0

    for i in range(1, len(T) - 1):
        mirror = 2 * C - i
        if i < R:
            P[i] = min(R - i, P[mirror])

        while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
            P[i] += 1

        if i + P[i] > R:
            C = i
            R = i + P[i]

    # Count occurrences of each palindrome
    count = {}
    for i in range(len(T)):
        if T[i] != '#':
            length = P[i]
            start = (i - length) // 2
            end = (i + length) // 2 - 1
            if (start, end) in count:
                count[(start, end)] += 1
            else:
                count[(start, end)] = 1

    # Calculate the number of crossing pairs
    total_pairs = 0
    for (start1, end1), cnt1 in count.items():
        for (start2, end2), cnt2 in count.items():
            if start1 <= end2 and start2 <= end1 and (start1, end1) != (start2, end2):
                total_pairs += cnt1 * cnt2

    return total_pairs % MOD

